CREATE OR REPLACE FUNCTION public.check_mission_status_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  allowed text[];
BEGIN
  IF OLD.status = NEW.status THEN
    RETURN NEW;
  END IF;

  CASE OLD.status
    WHEN 'pending' THEN
      allowed := ARRAY['pending_provider_approval', 'assigned', 'cancelled', 'expired'];
    WHEN 'pending_provider_approval' THEN
      allowed := ARRAY['assigned', 'rejected', 'cancelled', 'expired'];
    WHEN 'assigned' THEN
      allowed := ARRAY['in_progress', 'cancelled'];
    WHEN 'in_progress' THEN
      allowed := ARRAY['awaiting_payment', 'cancelled'];
    WHEN 'awaiting_payment' THEN
      allowed := ARRAY['validated', 'dispute', 'cancelled'];
    WHEN 'validated' THEN
      allowed := ARRAY['paid'];
    WHEN 'completed' THEN
      allowed := ARRAY['paid'];
    WHEN 'dispute' THEN
      allowed := ARRAY['validated', 'cancelled'];
    WHEN 'expired' THEN
      allowed := ARRAY['pending'];
    WHEN 'rejected' THEN
      allowed := ARRAY['pending'];
    WHEN 'quote_submitted' THEN
      allowed := ARRAY['quote_sent', 'cancelled'];
    WHEN 'quote_sent' THEN
      allowed := ARRAY['quote_accepted', 'quote_refused', 'cancelled'];
    WHEN 'quote_accepted' THEN
      allowed := ARRAY['assigned', 'cancelled'];
    WHEN 'quote_refused' THEN
      allowed := ARRAY['pending', 'cancelled'];
    WHEN 'paid' THEN
      allowed := ARRAY[]::text[];
    WHEN 'cancelled' THEN
      allowed := ARRAY[]::text[];
    ELSE
      RAISE EXCEPTION 'Statut mission inconnu: %', OLD.status;
  END CASE;

  IF NOT (NEW.status = ANY(allowed)) THEN
    RAISE EXCEPTION 'Transition invalide: % → % (autorisés: %)',
      OLD.status, NEW.status, array_to_string(allowed, ', ');
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_mission_payment_confirmation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if current_user in ('postgres','service_role') then return new;end if;
 if tg_op='INSERT' then
   if new.status='paid' or new.paid_at is not null or new.payment_intent_id is not null or new.stripe_payment_intent_id is not null then
     raise exception 'Payment confirmation is server-managed' using errcode='42501';
   end if;
 elsif (new.status='paid' and old.status is distinct from 'paid')
   or new.paid_at is distinct from old.paid_at
   or new.payment_intent_id is distinct from old.payment_intent_id
   or new.stripe_payment_intent_id is distinct from old.stripe_payment_intent_id then
   raise exception 'Payment confirmation is server-managed' using errcode='42501';
 end if;
 return new;
end;$function$

CREATE OR REPLACE FUNCTION public.guard_payment_prices()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if current_user in ('postgres', 'service_role') or coalesce(public.is_admin(), false) then return new; end if;
  if tg_table_name = 'missions' then
    if new.owner_id is distinct from old.owner_id then
      raise exception 'Mission ownership is immutable' using errcode = '42501';
    end if;
    if new.fixed_rate is distinct from old.fixed_rate then
      if auth.uid() <> old.owner_id or not (
        old.status in ('pending', 'pending_provider_approval')
        or (old.status = 'in_progress' and new.fixed_rate >= old.fixed_rate)
      ) then raise exception 'Mission price is locked' using errcode = '42501'; end if;
    end if;
    if old.status in ('validated', 'paid') and new.status not in ('validated', 'paid', 'dispute', 'cancelled') then
      raise exception 'Validated mission cannot return to editable pricing' using errcode = '42501';
    end if;
  elsif tg_table_name = 'mission_quotes' then
    if new.provider_id is distinct from old.provider_id or new.mission_id is distinct from old.mission_id
       or new.emergency_request_id is distinct from old.emergency_request_id or new.intervention_id is distinct from old.intervention_id then
      raise exception 'Quote parties are immutable' using errcode = '42501';
    end if;
    if new.repair_cost is distinct from old.repair_cost or new.total_ht is distinct from old.total_ht
       or new.tva_rate is distinct from old.tva_rate or new.is_vat_exempt is distinct from old.is_vat_exempt then
      if auth.uid() <> old.provider_id or old.status <> 'pending' then
        raise exception 'Only the provider can revise a pending quote price' using errcode = '42501';
      end if;
    end if;
  elsif tg_table_name = 'emergency_bids' then
    if new.provider_id is distinct from old.provider_id or new.mission_id is distinct from old.mission_id
       or new.emergency_request_id is distinct from old.emergency_request_id then
      raise exception 'Bid parties are immutable' using errcode = '42501';
    end if;
    if new.travel_cost is distinct from old.travel_cost or new.diagnostic_cost is distinct from old.diagnostic_cost then
      if auth.uid() <> old.provider_id or old.status <> 'pending' then
        raise exception 'Only the provider can revise a pending bid price' using errcode = '42501';
      end if;
    end if;
  end if;
  return new;
end;
$function$

