CREATE OR REPLACE FUNCTION public.create_rotation_missions_from_ical()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_assignment   public.concierge_assignments%ROWTYPE;
  v_owner_id     uuid;
  v_prop_name    text;
  v_fixed_rate   numeric;
  v_mission_id   uuid;
  v_guest        text;
  v_body         text;
BEGIN
  -- Ignorer les créneaux bloqués (Airbnb "Not available" / Booking "BLOCKED")
  v_guest := COALESCE(NEW.guest_name, '');
  IF v_guest = 'Indisponible' THEN
    RETURN NEW;
  END IF;

  -- Défensif : si une mission est déjà liée à cette réservation, ne rien faire
  IF EXISTS (SELECT 1 FROM public.missions WHERE reservation_id = NEW.id) THEN
    RETURN NEW;
  END IF;

  -- Récupérer l'assignment concierge ACTIF pour cette propriété
  SELECT *
    INTO v_assignment
    FROM public.concierge_assignments
   WHERE property_id = NEW.property_id
     AND status      = 'active'
   LIMIT 1;

  -- Pas de concierge assigné → rien à faire (flux normal iCal inchangé)
  IF v_assignment.id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Propriétaire + infos propriété
  SELECT owner_id, name, fixed_rate
    INTO v_owner_id, v_prop_name, v_fixed_rate
    FROM public.properties
   WHERE id = NEW.property_id;

  IF v_owner_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Création de la mission de rotation pré-assignée au concierge
  INSERT INTO public.missions (
    property_id,
    owner_id,
    assigned_provider_id,
    reservation_id,
    mission_type,
    status,
    mode,
    scheduled_date,
    description,
    fixed_rate,
    services,
    linge_fourni
  ) VALUES (
    NEW.property_id,
    v_owner_id,
    v_assignment.provider_id,
    NEW.id,
    'concierge',
    'assigned',
    'fixed',
    NEW.check_out,
    'Rotation concierge — départ ' || COALESCE(NULLIF(v_guest, ''), 'invité'),
    v_fixed_rate,
    v_assignment.services,
    v_assignment.linge_fourni
  ) RETURNING id INTO v_mission_id;

  -- Notification push + in-app au concierge
  v_body := 'Nouvelle rotation à '
         || COALESCE(v_prop_name, 'un logement')
         || ' le '
         || to_char(NEW.check_out::date, 'DD/MM/YYYY');

  BEGIN
    PERFORM public._send_push(
      v_assignment.provider_id,
      '🧹 Nouvelle rotation concierge',
      v_body,
      v_mission_id,
      'mission'
    );
  EXCEPTION WHEN OTHERS THEN
    -- La mission est déjà créée : on ne bloque pas l'insert si la push échoue
    NULL;
  END;

  RETURN NEW;
END;
$function$
